(function(root){
 'use strict';
 const numeric=v=>v!==''&&v!==null&&v!==undefined&&Number.isFinite(Number(v))&&Number(v)>=0;
 const money=v=>Math.round(Number(v)*100)/100;
 function lineTotal(l){return ['price','quantity','times'].every(k=>numeric(l[k]))?money(Number(l.price)*Number(l.quantity)*Number(l.times)):null}
 function totals(lines=[]){const out={planned:0,actual:0,missingPlan:0,missingActual:0,lines:lines.length};for(const l of lines){const p=lineTotal(l);if(p===null)out.missingPlan++;else out.planned+=p;if(numeric(l.actual))out.actual+=Number(l.actual);else out.missingActual++;}out.planned=money(out.planned);out.actual=money(out.actual);out.complete=lines.length>0&&!out.missingPlan&&!out.missingActual;out.difference=out.complete?money(out.planned-out.actual):null;return out;}
 const row=(name,quantity='',times=1,area='')=>({name,area,price:'',quantity,times,actual:'',memo:''});
 function template(title){if(/かわらばん/.test(title))return [row('制作費'),row('印刷費',20000),row('地域新聞社・配布費',10000,1,'稲毛区・花見川区'),row('地域新聞社・配布費',10000,1,'中央区'),row('その他')];if(/フェア/.test(title))return [row('招待状・印刷',/冬/.test(title)?1100:''),row('同封物・印刷'),row('郵送費'),row('記念品'),row('焼きそば'),row('ポップコーン'),row('ゲーム・景品'),row('会場・備品'),row('その他')];if(/カレンダー/.test(title))return [row('できることカレンダー',1650),row('パナソニックカレンダー',350),row('郵送費',350)];return [row('印刷・制作費'),row('配布・郵送費'),row('その他')];}
 function periodFY(period){if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(period||''))return null;return Number(period.slice(0,4))-(Number(period.slice(5))<4?1:0)}
 function entry(e,y,book={}){const v={...e,...e.years?.[y]},id=e.id+'@'+y,r=book[id],month=v.start?Number(v.start.slice(5,7)):Number(v.month)||0;return {id,eventId:e.id,year:y,title:v.title,category:v.category,event:v,record:r||null,period:r?.period??(month?y+'-'+String(month).padStart(2,'0'):''),totals:totals(r?.lines||[])};}
 function entries(data,fy){const result=[],seen=new Set(),book=data.budgets||{};for(const e of data.events||[]){for(const y of [fy,fy+1]){if(e.repeat==='once'&&Number(e.year)!==y)continue;const item=entry(e,y,book),m=item.event.start?Number(item.event.start.slice(5,7)):Number(item.event.month)||0;if(item.record?periodFY(item.period)===fy||(!item.period&&y===fy):((m>=4&&y===fy)||(m>0&&m<4&&y===fy+1)||(!m&&y===fy))){result.push(item);seen.add(item.id)}}}for(const [id,r]of Object.entries(book)){if(seen.has(id)||periodFY(r.period)!==fy)continue;const split=id.lastIndexOf('@'),eid=id.slice(0,split),y=Number(id.slice(split+1)),e=(data.events||[]).find(x=>x.id===eid);const item=e?entry(e,y,book):{id,eventId:eid,year:y,title:r.title||'削除済みの予定',event:{},category:5,record:r,period:r.period,totals:totals(r.lines)};result.push(item)}return result.sort((a,b)=>(a.period||'9999').localeCompare(b.period||'9999')||a.title.localeCompare(b.title,'ja'));}
 function inPeriod(item,mode){if(mode==='annual')return true;if(!item.period)return false;const m=Number(item.period.slice(5)),pos=(m+8)%12;if(mode.startsWith('month:'))return m===Number(mode.split(':')[1]);if(mode.startsWith('quarter:'))return Math.floor(pos/3)===Number(mode.split(':')[1]);if(mode==='first')return pos<6;if(mode==='second')return pos>=6;return false;}
 function validateRecord(r){return r&&typeof r==='object'&&typeof r.period==='string'&&(r.period===''||periodFY(r.period)!==null)&&Array.isArray(r.lines)&&r.lines.length<=200&&r.lines.every(l=>l&&typeof l.name==='string'&&['price','quantity','times','actual'].every(k=>l[k]===''||numeric(l[k])));}
 const api={numeric,lineTotal,totals,template,periodFY,entries,inPeriod,validateRecord};root.YahataBudget=api;if(typeof module!=='undefined')module.exports=api;
})(typeof globalThis!=='undefined'?globalThis:this);
